{"content": "def execute(task, jobs):
    # Worker defaults missing legacy mode to all
    # Unknown job mode means missing or None, and such jobs stay included for every filter
    # Input job modes otherwise belong to remote/hybrid/office
    # excludes known mismatches, preserves input order and input objects

    result = []
    for job in jobs:
        # Get mode from job dict, default to None if missing
        job_mode = job.get("mode") if isinstance(job, dict) else None

        # Unknown mode (missing or None) means job stays included for every filter
        if job_mode is None:
            result.append(job)
        else:
            # Check if job mode matches task mode
            # task is the mode filter: "all", "remote", "hybrid", or "office"
            if task == "all":
                result.append(job)
            else:
                # Task mode is remote, hybrid, or office
                # Include job if job mode matches task mode
                if job_mode == task:
                    result.append(job)

    return result"}
